//! The benchmark harness's pure core (S17, SPEC D24, CONTRACT §19).
//!
//! This module owns the measurement semantics the conveyor inherited from `conveyor-bench`:
//!
//! - [`arm`] — what a run's label means, and when two runs may be compared at all.
//! - [`mcnemar`] — the exact two-sided paired test the comparison reports.
//! - [`specgen`] — the Rust port of swebench 5.0.2's `make_test_spec` eval-script transform;
//!   the seed artifact is generated by it, and a golden test (from the pinned harness, run once
//!   during development) proves byte equality.
//! - [`parsers`] — the per-repo log parsers, ported from `swebench.harness.log_parsers`.
//! - [`grade`] — the verdict ladder, ported from `grader.py::grade_log` and swebench's
//!   `get_eval_report`.
//!
//! Nothing here performs IO. The seed tool (`tools/seed-benchmark`) does the reading; the store
//! and the sandbox write what these functions resolved.

pub mod arm;
pub mod grade;
pub mod mcnemar;
pub mod parsers;
pub mod specgen;

pub use arm::{Arm, ArmError, Oracle, Pipeline, Prompt};
pub use grade::{
    APPLY_PATCH_FAIL, APPLY_PATCH_PASS, EVAL_MARKER, Grade, GradeStatus, START_TEST_OUTPUT,
    TEST_EXIT_CODE, TIMEOUT_MARKER, TestReport, TestStatuses, grade_log,
};
pub use mcnemar::{CompareError, McNemar, PairedCounts, compare};
pub use specgen::{END_TEST_OUTPUT, eval_script, oracle_files};
